CREATE OR ALTER PROCEDURE [dbo].[SP_AssignRoleToUser] @UserId INT, @RoleName NVARCHAR(50) AS BEGIN SET NOCOUNT OFF; DECLARE @RoleId INT SELECT @RoleId = RoleId FROM ROLES WHERE RoleName = @RoleName AND IsActive = 1 IF @RoleId IS NOT NULL BEGIN IF NOT EXISTS (SELECT 1 FROM USERROLES WHERE UserId = @UserId AND RoleId = @RoleId) BEGIN INSERT INTO USERROLES (UserId, RoleId) VALUES (@UserId, @RoleId) END END END